  if {$::write_ok < 0} {
    set ::write_ok [expr ![catch {db5 eval { BEGIN IMMEDIATE }}]]
    catch { db5 eval ROLLBACK }
  }
  if {$::read_ok < 0} {
    set ::read_ok [expr ![catch {db5 eval { SELECT * FROM t1 }}]]
