  # connection [db6]
  catch { db6 eval { BEGIN ; SELECT * FROM sqlite_master } } msg
}
if {$method == "xShmLock" } {
  set details [lindex $args 2]
  if {$details == "0 1 lock exclusive"} { set ::seen_writer_lock 1 }
